def parse_cpstart_file(filepath):
    params = {}
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or '=' not in line:
                continue
            key, val = line.split('=', 1)
            key = key.strip()
            val = val.strip().strip("'")
            try:
                if '.' in val or 'e' in val.lower():
                    val = float(val)
                else:
                    val = int(val)
            except ValueError:
                pass
            params[key] = val
    return params

def parse_raw_seqpar(filepath):
    params = {}
    seqpar_block = False
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if line.startswith('$SEQPAR'):
                seqpar_block = True
                continue
            if line.startswith('$END') and seqpar_block:
                break
            if seqpar_block:
                # example line: hzpppm=400.268
                if '=' in line:
                    key, val = line.split('=', 1)
                    key = key.strip()
                    val = val.strip()
                    try:
                        if '.' in val or 'e' in val.lower():
                            val = float(val)
                        else:
                            val = int(val)
                    except ValueError:
                        val = val.strip("'")
                    params[key] = val
    return params

